INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(1000, 0, 10, 0, 0, 0, 'Duskwood', 'Duskwood was once called Brightwood, a green and peaceful stretch of the forests south of Stormwind, dotted with farms and hamlets. Then a foul magic seeped into the land, and the woods fell under a night that never fully lifts. The dead do not rest here. The necromancer Morbent Fel commands skeletons and ghouls from the graveyards of Raven Hill, and worgen have appeared as if from thin air to overrun the groves and orchards. Dark Riders out of Deadwind Pass have slaughtered a farmer''s family in search of a lost relic, and the Defias Brotherhood squats in abandoned farmsteads. When Stormwind recalled its guards, the people of Darkshire raised the Night Watch to defend themselves, and they bitterly resent the capital that left them alone. At the forest''s heart the Twilight Grove keeps a gateway to the Emerald Dream, now guarded by green dragons twisted by nightmare.', 'warcraft.wiki.gg/wiki/Duskwood (originally called Brightwood; Morbent Fel behind the undead; Twilight Grove portal; Dragons of Nightmare); warcraft.wiki.gg/wiki/Brightwood_Grove (Brightwood the original name); quest 146 description (Night Watch formed because Stormwind left when foul magic seeped into the land); quest 56 description (Stormwind retracted its guards); quest 173 reward text (worgen appear out of thin air); quest 95 description (Dark Riders from Deadwind Pass); quest 1244 description (Defias at Addle''s Stead); quest 269 description (Stormwind has forsaken Darkshire); creature_text 270, 271'),
(1001, 1, 10, 1, 0, 0, 'The Hushed Bank', 'The Hushed Bank is the quiet northwestern shore of Duskwood''s river, close to the Westfall border. Here Sven Yorgen keeps a small camp with his companion Lars, far from the safety of Darkshire. They are so few that they cannot spare a man to fetch supplies, and the Carevin family sends what it can with any willing traveler. The two must hunt for their own food, and starving and rabid dire wolves come out of the trees whenever meat is carried back to camp. Venom web spiders and green recluses nest along the bank, and from this lonely post Sven plots against the necromancer to the east.', 'quest 164 description (camp at the northwestern edge, too few to fetch supplies); quest 226 description (Lars, hunting, dire wolves, necromancer to the east); zone_areas: Sven Yorgen 311 and Lars 893 stand in area 1097, with Pygmy Venom Web Spider, Venom Web Spider, Green Recluse, Rabid and Starving Dire Wolf'),
(1002, 1, 10, 2, 0, 0, 'The Darkened Bank', 'The Darkened Bank follows the river that runs the whole length of Duskwood''s northern edge. Starving and rabid dire wolves hunt along it, the rare wolf Lupos among them, while venom web spiders nest between the foothills and the water. Their legs are prized in Darkshire, where the tavern cook turns them into a tangy dish he insists on calling crab cakes. Ghouls and skeletons stray down to the banks from the cemeteries to the south. Between the wolves, the spiders and the restless dead, few travelers care to linger beside these dark waters.', 'zone_areas: area 799 spans the north edge; Starving Dire Wolf x35, Rabid Dire Wolf x22, Pygmy Venom Web Spider, Venom Web Spider, Lupos 521, Brain Eater, Bone Chewer, Skeletal Warder; quest 93 description (spider legs, spiders nest to the north between the foothills and the river, crab cakes); quest 226 description (wolves near the river); quest 245 completion text (men hanging in webs)'),
(1003, 1, 10, 3, 0, 0, 'Addle''s Stead', 'Just south of the road from Westfall, where it first enters Duskwood, stands Addle''s Stead, a farm abandoned to the darkness and then claimed by the Defias Brotherhood. Night runners, night blades and Defias enchanters lurk in its fields, its barn and its little farmhouse. The Night Watch counts any Defias presence a threat, and Watcher Backus heard reports that agents of the Brotherhood had gathered here not long ago, as though something important had taken place. A docket recovered from the farm proved far too intricate to be a decoy, and it was carried to Stormwind, where agents were searching for a missing diplomat.', 'warcraft.wiki.gg/wiki/Addle''s_Stead (abandoned when darkness spread, taken over by Defias; pre-Cataclysm NPCs); quest 1244 description (Defias gathered at Addle''s Stead, south of the road from Westfall); quest 1245 description (too complex to lead you astray, take it to Trias); quest 1243-1245 titles (The Missing Diplomat); zone_areas: Defias Night Blade 909, Night Runner 215, Enchanter 910, Defias Strongbox in area 536'),
(1004, 1, 10, 4, 0, 0, 'Raven Hill', 'Raven Hill was once a town of western Duskwood, but it has long stood abandoned, its houses empty and its streets given over to the Unseen, shadowy things that drift through the ruins. Lately someone has been seen there. Calor of Darkshire noticed shadows moving on two nights running and, on another, a light in a window. The haunting turned out to be Jitters, a nervous fugitive who has hidden here for weeks living on grubs and weeds, certain he is being hunted. A goblin trader named Bliztik has also found shelter among the deserted buildings, and the graveyard that gives the town its grim fame lies just to the north.', 'warcraft.wiki.gg/wiki/Raven_Hill (abandoned town, haunted by the Unseen, Jitters and Bliztik); warcraft.wiki.gg/wiki/Duskwood (Grand Hamlet and Raven Hill as towns of the region); quest 163 description (Calor saw shadows and a light); quest 5 description (hiding for weeks, grubs and weeds); page_text 246 (abandoned town of Raven''s Hill); zone_areas: Unseen 3094 x11, Jitters 288, Bliztik 2481 in area 94; warcraft.wiki.gg/wiki/Raven_Hill (located in western Duskwood, south of the cemetery)'),
(1005, 1, 10, 5, 0, 0, 'Raven Hill Cemetery', 'North of the abandoned town sprawls the Raven Hill Cemetery, which by the end of the wars had grown to dominate much of the area. It holds the graves of many who met tragic ends, and few of them lie still. Skeletal horrors walk among the headstones, ghouls such as flesh eaters, bone chewers and rotted ones claw at the earth, and plague spreaders infest the eastern mausoleum. Grave robbers pick over whatever the dead leave behind. One stone bears only the name Eliza and a prayer that the earth might satisfy her hunger, and close by, on the cemetery''s edge, the old hermit Abercrombie keeps his lonely shack.', 'page_text 66 (cemetery near Raven''s Hill now dominated much of the area); warcraft.wiki.gg/wiki/Duskwood (graves of many who have known tragic fates); quest 57, 58 descriptions (skeletal horrors, plague spreaders in the eastern mausoleum); quest 133 description (ghoul types); page_text 731 (Eliza''s Tombstone: Beloved wife, may the earth sate your hunger); quest 157 (shack north of the cemetery); posarea: Abercrombie 289 and Eliza''s Tombstone 37 both in area 492; zone_areas: Skeletal Horror, Plague Spreader, Flesh Eater, Bone Chewer, Rotted One, Grave Robber in 492'),
(1006, 1, 10, 6, 0, 0, 'Forlorn Rowe', 'The Forlorn Rowe is the hill on the northern edge of the Raven Hill Cemetery, and the house at its top is the lair of the necromancer Morbent Fel. From there he looks down on the graves below and commands the dead of Duskwood. Skeletal raiders, warders and healers guard the slopes, and a skeletal officer called Commander Felstrom walks among them. Sven Yorgen has seen the Dark Riders speaking with Fel at this house. Out past the house, Darkshire buried the disgraced knight Morgan Ladimore without ceremony, and the earth of his weathered grave has since been found disturbed.', 'warcraft.wiki.gg/wiki/Forlorn_Rowe (hill on the northern edge of Raven Hill Cemetery, Morbent Fel''s home); quest 55 description (house atop the hill overlooking the cemetery); quest 268 reward text (riders seen speaking with Morbent Fel at the Forlorn Rowe); quest 323 (Skeletal Raiders, Healers, Warders); quest 228 description (buried him out past the house on the hill); quest 225 description (grave recently disturbed); page_text 71 (buried without ceremony); zone_areas: Morbent Fel 1200, Mor''Ladim 522, Commander Felstrom 771, A Weathered Grave 61 in area 243'),
(1007, 1, 10, 7, 0, 0, 'The Yorgen Farmstead', 'In western Duskwood, southeast of Sven Yorgen''s camp, lies the farm he once worked with his wife and children. While Sven was away in Darkshire, Dark Riders out of Deadwind Pass descended on the farmstead demanding a relic called the Scythe of Elune, and they slaughtered his family. A frightened stranger hiding in the barn saw everything, and before he fled he buried a half finished journal behind an old stump nearby. The farm was never reclaimed. Defias night runners, night blades and enchanters now lurk around the empty buildings, and young black ravagers prowl the woods around them.', 'quest 95 description (farm to the southeast, Dark Riders, shadowy figure, old stump); quest 230 description (small dirt-stained book); page_text 192-203 (Jitters hid in the barn; Sven left for Darkshire; Riders asked for the Scythe of Elune); warcraft.wiki.gg/wiki/Yorgen_Farmstead (Defias held it, pre-Cataclysm); zone_areas: Defias Night Runner, Night Blade, Enchanter, Young Black Ravager, Mound of loose dirt 59 in area 245'),
(1008, 1, 10, 8, 0, 0, 'Vul''Gol Ogre Mound', 'In southern Duskwood, near where the road turns south toward Stranglethorn Vale, a basin of ruined farmhouses has become the Vul''Gol Ogre Mound, home of the Splinter Fist ogres. Warriors, fire weavers and taskmasters crowd the hollow under a brute named Zzarc''Vul, who wears a monocle large enough to serve as the lens of a stargazing device. The ogres raid beyond their mound as well. When the hermit Abercrombie wandered too far from home picking herbs, a band of them chased him off and carried his crate of tools and herbs back to their lair.', 'warcraft.wiki.gg/wiki/Vul''Gol_Ogre_Mound (basin in southern Duskwood southwest of the road split, ruined farmhouses, Splinter Fist led by Zzarc''Vul); quest 181 description (monocle as the only large enough lens); quest 134 description (ogres stole Abercrombie''s crate); zone_areas: Splinter Fist Warrior, Fire Weaver, Ogre, Taskmaster, Firemonger and Abercrombie''s Crate 119 in area 93'),
(1009, 1, 10, 9, 0, 0, 'Twilight Grove', 'At the heart of Duskwood stands the Twilight Grove, where a great tree rises above a moonwell and a gazebo of night elf design, strange sights so far from Kalimdor. The grove holds one of the few gateways to the Emerald Dream, the realm watched over by the green dragonflight. It is no refuge. Dragons of Ysera''s flight, corrupted and driven mad by nightmare, have come out to guard the portal and to spread their madness. The great green dragon Taerar has been seen here, crying that peace is but a fleeting dream and loosing his children of madness upon the world.', 'warcraft.wiki.gg/wiki/Twilight_Grove (great tree, moonwell, night elf gazebo, one of four Emerald Dream portals, Dragons of Nightmare); creature_text 14890 (Taerar); DB: Taerar 14890 spawn at -10428.8,-392.2, posarea area 856'),
(1010, 1, 10, 10, 0, 0, 'The Rotting Orchard', 'Southwest of Darkshire the orchards of Duskwood have gone to rot, and the worgen have overrun them. Nightbane dark runners, which make up the bulk of the worgen packs, roam between the twisted trees alongside shadow weavers, and the Unseen drift through the gloom. Hunters of the Carevin family come here to thin their numbers, yet each pack they cut down seems to be replaced. Just to the east lies the mine called Roland''s Doom, where the worgen were first found, and where the fiercest of them now make their den around their bonfires.', 'quest 221 description and reward text (Dark Runners bulk of worgen, overrun the Rotting Orchard southwest of town, numbers refill); quest 173 description (Shadow Weavers in Brightwood Grove and the Rotting Orchard); quest 222 description (Vile Fangs and Tainted Ones near caves and in the mine to the south, bonfires); quest 1043 description (mine to the south where worgen were first found); warcraft.wiki.gg/wiki/Roland''s_Doom (due east of the Rotting Orchard); zone_areas: Nightbane Dark Runner x34, Shadow Weaver x13, Unseen in area 241'),
(1011, 1, 10, 11, 0, 0, 'Brightwood Grove', 'West of Darkshire the forest opens into Brightwood Grove, a name kept from the days when the whole wood was called Brightwood. Nothing bright remains. Nightbane worgen keep camps throughout the grove, shadow weavers and dark runners among them, and the dreaded worgen Fenros stalks between them. Black ravagers and their mastiffs hunt in packs across the fields, and green recluse spiders spin in the trees. Calor of the Carevin family, scoffing at the name, sends those who would join his master''s cause here first to prove themselves against the worgen.', 'warcraft.wiki.gg/wiki/Brightwood_Grove (west of Darkshire, Brightwood the original name, worgen camps, Fenros); quest 173 description (Brightwood Grove, bright, hah!); zone_areas: Nightbane Worgen x25, Dark Runner x23, Shadow Weaver x14, Fenros 507, Black Ravager, Black Ravager Mastiff, Green Recluse in area 242'),
(1012, 1, 10, 12, 0, 0, 'Darkshire', 'Darkshire, once called Grand Hamlet, took its grim name after darkness fell on the forest. It is the heart of human Duskwood and the home of the Night Watch. Lord Ello Ebonlocke governs from the town hall with a council that complains endlessly of Stormwind''s neglect, while Commander Althea Ebonlocke leads the watchers. Clerk Daltry keeps the town registry, the Scarlet Raven Tavern serves Chef Grual''s spider leg crab cakes, Madame Eva reads the cards beside the square, and the Carevin family plots its own war on evil. The stargazer Viktori seeks answers in the sky, and a draenei anchorite has come from afar to lend aid.', 'warcraft.wiki.gg/wiki/Darkshire (originally Grand Hamlet, renamed after the corruption); page_text 67 (Darkshire, as it was now called); quest 145 description (Darkshire in the heart of Duskwood); creature_text 269, 270, 271 (council members); quests 66, 67, 78, 93, 148, 223; quest 174 description (Viktori, truth beyond magic); quest 9429 (Anchorite Delan 17104); zone_areas: all named NPCs above in area 42; warcraft.wiki.gg/wiki/Darkshire (Grand Hamlet renamed Darkshire, cited to Warcraft: Legends Volume 2, Warrior: Divided, 2008)'),
(1013, 1, 10, 13, 0, 0, 'Tranquil Gardens Cemetery', 'Just south of Darkshire lies the Tranquil Gardens Cemetery, whose name has become a bitter joke. Skeletal warriors and mages rise among the graves, and the Night Watch sends its first volunteers here to cut them down before they reach the town. A deranged ghoul haunts the ruined church, and it may be the one that carried off a looking glass the stargazer Viktori once threw away behind a barn. In the hills nearby stands the old farmhouse of Blind Mary, a spirit who tore out her own eyes and believes herself a monster, and who still begs visitors not to look at her.', 'quest 56 description (Tranquil Gardens just south of Darkshire, Skeletal Warriors and Mages); warcraft.wiki.gg/wiki/Tranquil_Gardens_Cemetery (Blind Mary''s house just north, Insane Ghoul in the ruined church); quest 177 description (looking glass discarded behind the barn, Insane Ghoul may have picked it up); quest 149 description and completion text (Blind Mary tore out her eyes, please look away); zone_areas: Skeletal Warrior x15, Skeletal Mage x12, Insane Ghoul 511 in area 121; quest 154 description (I''m a monster)'),
(1014, 1, 10, 14, 0, 0, 'Manor Mistmantle', 'Just north of Darkshire stands the house of Stalvan Mistmantle, once a scholar and tutor, now a murderous recluse. The grounds have gone to rot. Fetid corpses shamble along the overgrown paths and around the house, and the Unseen drift nearby. Only one living thing seems to thrive there, a single flower in the garden called the Tear of Tilloa, bearing the name of the girl whose rejection turned Stalvan to murder. The Night Watch had kept a suspicious eye on the manor for some time before proof of its master''s crimes was finally found.', 'quest 98 description (his cottage just north of town); warcraft.wiki.gg/wiki/Manor_Mistmantle (rotten grounds, minions, single flower Tear of Tilloa); quest 80 description (I have had my eye on that creep for quite some time); page_text 20-24 (Tilloa); zone_areas: Stalvan 315, Fetid Corpse x14, Unseen, Tear of Tilloa 321 in area 1098'),
(1015, 1, 10, 15, 0, 0, 'Beggar''s Haunt', 'In the northeast of Duskwood, close to the road into Deadwind Pass, stands Beggar''s Haunt, an abandoned scout tower of the Stormwind Guard. Its new tenants are Forsaken. Deathstalker Zraedus and Apothecary Faustin of the Royal Apothecary Society belong to an expeditionary force sent at Varimathras''s command to survey the southern lands, and they would rather nobody knew they were here. When a human infiltrator was caught spying on the tower and carried off to the orcs of Stonard, Faustin offered to brew a truth serum for the prisoner, and made little effort to hide what the serum truly was.', 'warcraft.wiki.gg/wiki/Beggar''s_Haunt (abandoned Stormwind Guard scout tower, Zraedus and Faustin, pre-Cataclysm); quest 1372 description (expeditionary force at Varimathras''s behest, infiltrator spying on Beggar''s Haunt, taken to Stonard); quest 1372 reward text (last thing we need is a busybody); quest 1383 reward text (prepare the pois- I mean the truth serum); zone_areas: Apothecary Faustin 5414, Deathstalker Zraedus 5418, Faustin''s Alchemy Set in area 576'),
(1016, 2, 10, 1, 1, 0, 'Commander Althea Ebonlocke', 'Commander Althea Ebonlocke leads the Night Watch, the militia Darkshire raised for itself after Stormwind withdrew its commissioned guards. She has never had enough watchers, and she warns every traveler to keep to the roads and move only by day. The defense of the town comes before everything, and she has little patience for dead end leads, yet she had kept a wary eye on Stalvan Mistmantle long before proof of his guilt arrived, and ordered his execution the moment it did. She also sends volunteers against the undead of the cemeteries and against Mor''Ladim, who has slain some of her strongest watchers.', 'npc_text 50029 (stick to the roads, travel by day, numbers small); quest 56 description; quest 58 description (not enough watchers); quest 79 completion text (Darkshire''s defense is my priority, no time for dead-end leads); quests 80, 97, 98; quest 228 description and completion text'),
(1017, 2, 10, 2, 1, 0, 'Lord Ello Ebonlocke', 'Lord Ello Ebonlocke is the Mayor of Darkshire, presiding over its council from the town hall. He has no illusions about his town''s position. The Night Watch exists because Stormwind abandoned Duskwood when the foul magic came, and when Lakeshire begged for watchmen he refused, certain Darkshire would be overrun before they reached the forest''s edge. He passes sentence on the worst of criminals, condemning to death a man who sold corpses to Morbent Fel. When a letter in an ancient script reached him from a hermit he had never heard of, he had it translated and found himself facing the Embalmer of a children''s tale.', 'quest 146 description; creature_text 263; quest 377 description (Lord Ebonlocke''s sentence on Dextren Ward); quest 160 completion and reward text (does not know Abercrombie, ancient language); quests 251, 252, 253'),
(1018, 2, 10, 3, 1, 0, 'Madame Eva', 'Madame Eva reads the cards and listens to the whispers of spirits from her home on the Darkshire square. The stars, she says, speak of horrors waiting in the night. When a disturbance rippled through her veins she knew her granddaughter Alyssa was in danger, and Death stared up at her from the table. A long trance gave her one name, Stalvan, and that premonition began the hunt that unmasked a murderer. She practices other old arts too, spinning thread from ghost hair that can bind spirits, and enchanting totems that punish anyone who raises a hand against their bearer.', 'quest 66 description (Alyssa, cards, trance, Stalvan); quest 98 reward text; quest 148 description (her home on the Darkshire square); quests 149, 157 (Ghost Hair Thread binds evil spirits); quest 101 description and reward text; creature_text 265; DB: Alyssa Eva 1673 in Darkshire'),
(1019, 2, 10, 4, 1, 0, 'Sven Yorgen', 'Sven Yorgen farmed land in western Duskwood until the day he went to Darkshire and came home to find his wife and children murdered by Dark Riders from Deadwind Pass. He rode after the killers, and so never learned what the shadowy figure he glimpsed by his barn had buried. Now he keeps a small camp on the Hushed Bank with his companion Lars, living off the land and welcoming anyone who will join his fight. Once he learned that the riders had been seen with the necromancer Morbent Fel, the necromancer''s death became his revenge, though he would send no one against Fel without first testing their skill.', 'quest 95 description; page_text 193 (Sven left his farm for Darkshire); quest 164 description and completion text; quest 226 description; quest 268 reward text; quest 323 description; quest 55 description (be the instrument of my revenge)'),
(1020, 2, 10, 5, 1, 0, 'Jitters', 'Jitters earned his name through a lifelong habit of flinching from danger, and that caution may be all that has kept him alive. By his own confession he was working in the mine called Roland''s Doom, on behalf of the Defias Brotherhood, when he pulled a strange scythe from the rubble, and soon afterward worgen burst from the darkness and slaughtered his fellows. He fled, hid in Sven Yorgen''s barn, and watched helplessly as Dark Riders hunting that very scythe killed Sven''s family. Since then he has moved from one hiding place to the next, and now cowers in the empty town of Raven Hill, starving and certain he will be found.', 'page_text 85, 186-203, 246 (Jitters'' Completed Journal); quest 163 reward text; quest 5 description; quest 453 reward text; quest 268 description; warcraft.wiki.gg/wiki/Jitters (a member of the Defias Brotherhood infiltrating Duskwood)'),
(1021, 2, 10, 6, 1, 0, 'Jonathan Carevin', 'Jonathan Carevin heads the Carevin family of Darkshire, hunters of demons, undead and other monstrosities who wage their own war against evil in the forest. He is a busy and suspicious man who trusts no one unwilling to aid the cause, and he watches the townsfolk for any who give comfort to the enemies of the Light. Among his followers is Calor, who joined the family in disgust at the complacency of the Night Watch. Calor tests recruits against the worgen and recommends the worthy to his master. The Carevins have resolved to contain the worgen, though they lack the strength to end the threat at its root.', 'quest 1042 description (Carevin family, hunters of demons, undead and monstrosities; Jonathan head of the household); quest 223 reward text (cold reception, trust none); page_text 63 (Calor''s Note, townsfolk under suspicion); quest 173 description (Calor disillusioned by the Watch); quest 1043 reward text (influence not large enough, contain the worgen)'),
(1022, 2, 10, 7, 1, 0, 'Abercrombie', 'Abercrombie is a frail old man who lives alone in a shack beside the Raven Hill Cemetery. He once came to Darkshire often for supplies, but has not been seen there in a long while. He seems harmless, asking travelers for ghost hair thread, strong liquor, ghoul ribs and a crate of tools stolen by ogres, and laughing a little too hard when they succeed. His slips of the tongue tell another story. He is the Embalmer of Darkshire''s children''s tales, once a kindly alchemist who, maddened by the death of his wife Eliza, used dark magic to place his own heart within her body and bring her back.', 'quest 165 description and reward text; quests 148, 157, 158, 159, 133, 134 (requests; Thank the Nec-); quest 160 description (Hahahaha); quest 253 description (the Embalmer, Eliza, his heart); page_text 235 (signed The Embalmer); warcraft.wiki.gg/wiki/Abercrombie (necromancer, the Hermit and the Embalmer, pre-Cataclysm location)'),
(1023, 2, 10, 8, 0, 0, 'Stalvan Mistmantle', 'Stalvan Mistmantle of Silverpine studied under Headmaster Crillian and wandered south, becoming master of a new schoolhouse in Moonbrook. When troubles forced him from that post he became tutor to the noble Flintridge family, and fell for their eldest daughter, Tilloa, though she was promised to another. A begonia she gave him he took for love. When she introduced him to her suitor as a nice old man, his longing turned to fury, and his journal promised blood. The Flintridges were later massacred. Stalvan retreated to his manor north of Darkshire, where he still mistakes intruders for Tilloa.', 'page_text 16-19 (letters to Crillian, Moonbrook Schoolhouse, Stalvan Mistmantle of Silverpine); page_text 20-24 (Tilloa, begonia, suitor, nice old man, blood I shall spill); quest 72 description (Flintridge trust, massacre); quest 79 description (visiting nobles slaughtered); quest 98 description; creature_text 315 (Tilloa is that you?); warcraft.wiki.gg/wiki/Stalvan_Mistmantle (pre-Cataclysm section)'),
(1024, 2, 10, 9, 0, 0, 'Morbent Fel', 'Morbent Fel is the necromancer behind the undead plague of Duskwood. From his house atop the Forlorn Rowe he looks down on the Raven Hill Cemetery, and the skeletons and ghouls that fill it answer to his will. He keeps company with the Dark Riders of Deadwind Pass, and has woven enchantments about himself so strong that ordinary blows cannot reach him. At least one man, Dextren Ward, was caught selling him bodies from the cemetery. Bishop Farthing of Stormwind judged him immensely powerful, and only a weapon of holy Lightforge iron, salvaged from a ship lost with the Third Fleet of Kul Tiras, can strip his protections away.', 'warcraft.wiki.gg/wiki/Morbent_Fel (pre-Cataclysm: ruled the undead of Duskwood, magical barrier, Morbent''s Bane); quest 55 description; quest 268 reward text; quest 323 description (ally to the dark riders); quest 377 description (Dextren Ward); quest 269 reward text; quests 270, 321 (Third Fleet, Flying Osprey); quest 322 description'),
(1025, 2, 10, 10, 0, 0, 'Mor''Ladim', 'Mor''Ladim is the name taken by the restless corpse of Morgan Ladimore, once a noble knight of Duskwood who fought beside Uther the Lightbringer in the wars of Lordaeron. He came home to find his house in ruins and his wife Lys beneath a gravestone at Raven Hill. Mad with grief, he cut down three cemetery attendants who tried to restrain him, then turned his knife on himself. Buried without ceremony, he rose only days later, and now wanders the graveyard and the woods around it, slaying watchmen and travelers without reason. He never knew that his daughter Sarah had survived.', 'page_text 64-72 (The Story of Morgan Ladimore); quest 227 reward text (attacking watchmen on patrol and killing people); quest 228 description; quest 229 description (Sarah Ladimore lived)'),
(1026, 3, 10, 1, 1, 0, 'The Night Watch', 'When Stormwind recalled its commissioned guards, Darkshire formed the Night Watch from its own people, and Commander Althea Ebonlocke has never had enough of them. She sends volunteers first against the skeletons of the Tranquil Gardens Cemetery, then against the walking dead of Raven Hill, and finally into the eastern mausoleum to purge the plague spreaders. Watchers at a camp out on the road fight spiders that have strung up their comrades in webs. The town''s anger runs deep. When Lakeshire''s magistrate begged for watchmen, Lord Ebonlocke refused, and the magistrate was left suspecting treachery in Stormwind. When the House of Nobles imprisoned the corpse seller Dextren Ward rather than behead him, Councilman Millstipe offered a reward for the villain''s hand, a message to the nobles that Duskwood would not be ignored.', 'quests 56, 57, 58 (descriptions and reward texts); quest 245 description and completion text; DB: Watcher Dodds 888 at the road camp at -10923,-385; quests 145, 146 (descriptions and reward texts); quest 377 description and reward text'),
(1027, 3, 10, 2, 1, 0, 'The Legend of Stalvan', 'It began with Madame Eva''s dread for her granddaughter and a single name drawn from a trance. Clerk Daltry''s registry placed one Stalvan Mistmantle at the Moonbrook Schoolhouse, where an unsent letter in an old footlocker told of happier days, and a half scratched entry pointed on to the Lion''s Pride Inn in Goldshire. There a letter left behind by a terrified messenger years before led to the Canal District of Stormwind and the caretaker of the Flintridge estate, whose family had been massacred and whose possessions were bound for auction. Journal pages turned up in a crate there, in a chest at old Marshal Haggard''s house and in the keeping of Tavernkeep Smitts, telling of Stalvan''s obsession with young Tilloa. Daltry matched the hand to the registry signature, and Commander Ebonlocke ordered the murderer slain.', 'quests 66, 67, 68, 69, 70, 72, 74, 75, 78, 79, 80, 97, 98 (descriptions and reward texts); page_text 16-24'),
(1028, 3, 10, 3, 1, 0, 'Worgen in the Woods', 'Worgen seemed to appear in Duskwood out of thin air, and no matter how many fall, more spring up to fill their ranks. Calor of the Carevin family tests would-be recruits against them: first the shadow weavers of Brightwood Grove and the Rotting Orchard, then the dark runners who make up the bulk of the packs, and at last the vile fangs and tainted ones who den near the caves and in the mine to the south. The root of the plague lies in that mine, Roland''s Doom. A night elf priestess, Velinde Starsong, came there bearing the Scythe of Elune, a weapon granted by her goddess against the demons of Felwood, and she perished with the worgen loose and the scythe lost. Long afterward Jitters pulled the scythe from the rubble, and worgen poured out of the mine to slaughter his companions.', 'quests 173, 221, 222, 223 (descriptions and reward texts); quests 1041, 1042, 1043, 1044; creature_text 3946 (Velinde Starsong: scythe granted to fight the demons of Felwood; worgen run rampant, scythe lost); page_text 185-190 (Jitters found the scythe in Roland''s Doom, worgen came); warcraft.wiki.gg/wiki/Roland''s_Doom and Scythe_of_Elune (Velinde died at Roland''s Doom); gameobject 19030 Mound of Dirt at Roland''s Doom, event_script 664 summons Velinde Starsong''s spirit (3946) there'),
(1029, 3, 10, 4, 1, 0, 'Sven''s Revenge', 'Sven Yorgen asked one thing of those willing to help: find what the shadowy figure had buried behind the stump at his farm. The mound held an unfinished journal written by a witness to his family''s murder. Madame Eva sensed that its owner was a stranger to Darkshire, Clerk Daltry remembered selling him the blank book, and the tavernkeep recalled him writing at the bar before fleeing west. In Raven Hill, Jitters admitted the book was his and gave up his completed journal rather than face Sven. It told of the Scythe of Elune and the riders who killed for it, and Sven remembered seeing those riders with Morbent Fel. Bishop Farthing sent the would-be avenger to Menethil Harbor for Lightforge iron lost in a shipwreck, and a dwarven smith in Stormwind forged it into Morbent''s Bane, the weapon that broke the necromancer''s defenses.', 'quests 95, 230, 262, 265, 266, 453, 268, 323, 269, 270, 321, 324, 322, 325, 55 (descriptions and reward texts)'),
(1030, 3, 10, 5, 1, 0, 'Bride of the Embalmer', 'The Carevins worried about an old man who no longer came to town, and those sent to check found Abercrombie in his shack by Raven Hill, glad of help. He wanted ghost hair thread, which Madame Eva spun from a comb run through Blind Mary''s hair, Zombie Juice brewed at the Scarlet Raven from rot blossoms grown in skeletons'' skulls, ghoul ribs, and a crate of tools the ogres had stolen. Then he sent a cheerful note to Lord Ebonlocke. Translated by the historian Sirra Von''Indi, it was a gloating confession: the Embalmer had tricked his helpers into building a fiend of flesh, bone and twisted metal. The abomination Stitches marched on Darkshire and overran the Night Watch camp on the road before the defenders gathered in the town center to meet it. To break the Embalmer''s power, Ello sought the heart buried in his bride Eliza''s grave.', 'quests 165, 148, 149, 154, 157, 158, 156, 159, 133, 134, 160, 251, 401, 252, 253 (descriptions and reward texts); page_text 235 (Translated Letter from The Embalmer); creature_text 468 (Town Crier during the Stitches event); smart_scripts 263 and 412 (finishing quest 252 starts the Stitches march)'),
(1031, 3, 10, 6, 1, 0, 'A Daughter''s Love', 'A weathered grave out past the house on the hill bears the name Morgan Ladimore, and its earth has been disturbed. Sirra Von''Indi, who knew Morgan before the war, keeps a book telling his tale: the knight who came home from Lordaeron to find his family''s graves, killed three innocent attendants in his grief and then took his own life. Commander Ebonlocke knows the rest. The undead thing called Mor''Ladim wanders the cemetery, killing her watchers on patrol, and she asks for his skull. Only afterward does she admit that one of Morgan''s children lived: Sarah Ladimore now serves in the Night Watch. Sarah sends her ring to be laid on her father''s grave, and at last his spirit finds peace, giving up his sword Archeus to the one who brought him word.', 'quests 225, 227, 228, 229, 231 (descriptions and reward texts); page_text 64-72');
